'use strict';
/* Presentation only: no navigation, completion, history, or scrolling ownership. */
(()=>{
 const actionText=node=>[...node.childNodes].map(child=>child.textContent||'').join(' ');
 function classifyAction({text='',label='',href=''}={}){const words=String(text).replace(/[←→↩↪]/g,'').replace(/\s+/g,' ').trim(),name=(label||words).toLowerCase();if(/^previous\b/.test(name)||text.trim()==='←')return 'previous';if(/^next\b/.test(name)||text.trim()==='→')return 'next';if(/^(continue|start|open) walkthrough\b/i.test(words))return 'continue';if(/^(return|back|← back)\b/i.test(words)||/^return\b/i.test(name))return 'return';if(/^(map|show .*map|locate on .*map)$/i.test(words)||href.startsWith('#whiteorchard-map'))return 'map';return 'plain';}
 function categoryFor(rail){if(rail.closest('.main-region-selector,#regions,.exploration-deck'))return '#91b47c';if(rail.closest('#progress'))return '#c79e63';if(rail.closest('.diagram-view,#field-reference,#economy'))return '#b3cbd0';if(rail.closest('[id*=constellation]'))return '#5fc7b4';return '#8bb9bd';}
 function createPulse(pointer,{setTimer=window.setTimeout.bind(window),clearTimer=window.clearTimeout.bind(window)}={}){let timer=null;return {wake(){if(timer!==null)clearTimer(timer);pointer.classList.add('is-awake');timer=setTimer(()=>{pointer.classList.remove('is-awake');timer=null;},850);},quiet(){if(timer!==null)clearTimer(timer);timer=null;pointer.classList.remove('is-awake');}};}
 window.PhoenixVisualModel={actionText,classifyAction,categoryFor,createPulse};
 window.createPhoenixVisualSystem=function(){
  const railSelector='.quest-selector .deck,.main-region-orbit,.card-orbit,.command-deck,.quest-hub-rail,.diagram-rail,.diagram-cluster-rail,.objective-rail,.reference-rail,.home-shortcuts,.stage-ribbon,.scroll-index,.diagram-letter-strip';
  const actionSelector='button,a.primary-action,a.quest-hub-continue,.quest-hub-tools a,.quest-page-tools a,.stage-links>a,.diagram-detail-actions a,.merchant-links a,a.main-back,a.guide-search-return,a.tarot-open-action';
  const protectedSelector='.medallion-core,.quick-undo,.medallion-card,.art-navigation-button,.art-search-trigger,.art-warning-title,.desk-card,.main-region-card,.diagram-card,.quest-hub-card,.main-entry-card,.guide-search-result,.guide-search-recent-query,.diagram-letter-strip button,.leaflet-control button';
  const rails=new WeakMap(),markers=new Map(),controlOwners=new WeakMap(),bindings=[],changedLabels=new WeakSet();let pending=0,alive=true;
  const make=(tag,cls)=>{const node=document.createElement(tag);node.className=cls;return node;};
  function marker(node,color){if(markers.has(node))return node;node.textContent='';node.classList.add('wolf-pointer');node.setAttribute('aria-hidden','true');node.style.setProperty('--wolf-eye-color',color);const image=make('img','wolf-pointer-art');image.src='visual-art/wolf-pointer.webp';image.alt='';image.draggable=false;const eyes=make('span','wolf-pointer-eyes');node.append(image,eyes);markers.set(node,createPulse(node));return node;}
  function bind(rail,pointer){const pulse=markers.get(pointer);let until=0;const wake=()=>{until=Date.now()+1800;pulse.wake();};const movement=event=>{if((event.buttons||event.pointerType==='touch')&&Date.now()<until)pulse.wake();};const scroll=()=>{if(Date.now()<until)pulse.wake();};const key=event=>{if(['ArrowLeft','ArrowRight','Home','End','Enter',' '].includes(event.key))wake();};for(const [name,handler]of [['pointerdown',wake],['pointermove',movement],['wheel',wake],['keydown',key],['scroll',scroll]]){rail.addEventListener(name,handler,{passive:true});bindings.push([rail,name,handler]);}const controls=rail.nextElementSibling;if(controls?.matches('.main-deck-controls,.orbit-controls,.diagram-browse,.quest-hub-rail-controls,.objective-controls,.command-controls')){controls.addEventListener('click',wake,{passive:true});bindings.push([controls,'click',wake]);}const extra=rail.matches('.objective-rail')?[rail.closest('.quest-progress')?.querySelector('[data-objective-jump]')]:rail.closest('.diagram-browser-scroll')?[...rail.closest('.view').querySelectorAll('[aria-label="Find a named diagram"],[aria-label="Diagram source"]')]:[];for(const node of extra.filter(Boolean)){let owners=controlOwners.get(node);if(!owners){owners=new Set();controlOwners.set(node,owners);}if(!owners.has(pointer)){owners.add(pointer);node.addEventListener('change',wake,{passive:true});bindings.push([node,'change',wake]);}}rails.set(rail,pointer);}
  function decorateRail(rail){if(rails.has(rail))return;const color=categoryFor(rail);let pointer;
   if(rail.matches('.objective-rail')){const header=rail.closest('.objective-scroll-frame')?.querySelector('.objective-banner');if(!header)return;const cue=make('div','scroll-wolf-cue objective-scroll-cue is-on-paper');cue.setAttribute('aria-hidden','true');pointer=make('span','objective-wolf-pointer');marker(pointer,color);cue.append(pointer);rail.before(cue);}
   else if(rail.closest('.diagram-browser-scroll')){const frame=rail.closest('.diagram-browser-scroll');pointer=frame.querySelector('.diagram-compass-pointer');if(!pointer)return;marker(pointer,color);}
   else{const cue=make('div','scroll-wolf-cue');cue.setAttribute('aria-hidden','true');if(rail.closest('.reading-panel,.quest-hub-paper,.scroll-r16,.main-parchment,.hub-activities'))cue.classList.add('is-on-paper');pointer=make('span','scroll-wolf-pointer');marker(pointer,color);cue.append(pointer);rail.before(cue);}
   bind(rail,pointer);
  }
  function decorateAction(node){if(node.matches(protectedSelector))return;const purpose=classifyAction({text:actionText(node),label:node.getAttribute('aria-label')||'',href:node.getAttribute('href')||''});node.classList.add('phoenix-action');node.dataset.buttonPurpose=purpose;if(['previous','next'].includes(purpose)&&!node.children.length&&!changedLabels.has(node)){const clean=node.textContent.replace(/[←→]/g,'').trim();node.textContent=clean|| (purpose==='previous'?'Previous':'Next');changedLabels.add(node);}}
  function enhance(){pending=0;if(!alive)return;document.querySelectorAll(railSelector).forEach(decorateRail);document.querySelectorAll(actionSelector).forEach(decorateAction);}
  const queue=()=>{if(alive&&!pending)pending=requestAnimationFrame(enhance);};
  const needsEnhance=node=>node.nodeType===1&&[node,...node.querySelectorAll(railSelector+','+actionSelector)].some(item=>item.matches(railSelector)?!rails.has(item):item.matches(actionSelector)&&!item.matches(protectedSelector)&&!item.classList.contains('phoenix-action'));
  const observer=new MutationObserver(records=>{if(records.some(record=>[...record.addedNodes].some(needsEnhance)))queue();});observer.observe(document.body,{childList:true,subtree:true});
  const quiet=()=>{if(document.hidden)markers.forEach(pulse=>pulse.quiet());};document.addEventListener('visibilitychange',quiet);for(const name of ['phoenix:route-rendered','phoenix:progress-committed','phoenix:progress-undone'])window.addEventListener(name,queue);enhance();
  return {enhance,counts:()=>({pointers:markers.size,bindings:bindings.length}),destroy(){alive=false;observer.disconnect();if(pending)cancelAnimationFrame(pending);markers.forEach(pulse=>pulse.quiet());for(const [node,name,handler]of bindings)node.removeEventListener(name,handler);document.removeEventListener('visibilitychange',quiet);for(const name of ['phoenix:route-rendered','phoenix:progress-committed','phoenix:progress-undone'])window.removeEventListener(name,queue);}};
 };
})();
